?><section class="container page-section listing-head"><p class="eyebrow">Your saved shelf</p><h1>Favorites for later.</h1><p class="lead">Keep the recipes you want to make again close at hand.</p></section><section class="container page-section results-section"><?php if (!$recipes): ?><div class="empty-state"><h3>No saved recipes yet.</h3><p>Tap “Save favorite” on a recipe you want to keep nearby.</p><a class="button" href="<?= BASE_URL ?>/recipes.php">Browse recipes</a></div><?php else: ?><div class="recipe-grid"><?php foreach ($recipes as $recipe): ?><article class="recipe-card"><div class="recipe-image"><span><?= e(strtoupper(substr($recipe['category_name'], 0, 2))) ?></span></div><div class="recipe-card-body"><div class="card-meta"><span><?= e($recipe['category_name']) ?></span><span><?= date('M j, Y', strtotime($recipe['created_at'])) ?></span></div><h3><a href="<?= BASE_URL ?>/recipe_view.php?id=<?= (int) $recipe['id'] ?>"><?= e($recipe['title']) ?></a></h3><p><?= e($recipe['short_description']) ?></p><div class="card-footer"><small>by <?= e($recipe['author_name']) ?></small><span class="favorite-mark">★</span></div></div></article><?php endforeach; ?></div><?php endif; ?></section><?php require __DIR__ . '/includes/footer.php'; ?>
